1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Calculator</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0; min-height: 100vh; display: flex; align-items: center; justify-content: center;
11	    background: #eceef1; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
12	  }
13	  .calc {
14	    width: min(320px, 100vw - 32px); padding: 16px; border-radius: 20px;
15	    background: #1f2227; box-shadow: 0 12px 32px rgba(0,0,0,.25);
16	  }
17	  .display {
18	    height: 80px; margin-bottom: 16px; padding: 0 12px; border-radius: 12px;
19	    background: #2b2f36; color: #fff; font-size: 40px; text-align: right;
20	    line-height: 80px; overflow: hidden; white-space: nowrap; text-overflow: ellipsis;
21	  }
22	  .keys { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; }
23	  button {
24	    height: 60px; border: 0; border-radius: 12px; font-size: 22px; cursor: pointer;
25	    background: #3a3f47; color: #fff;
26	  }
27	  button:active { filter: brightness(1.25); }
28	  .op { background: #f59e0b; }
29	  .clear { background: #9ca3af; color: #111; }
30	  .wide { grid-column: span 2; }
31	</style>
32	</head>
33	<body>
34	<div class="calc">
35	  <div class="display" data-testid="calc-display" data-value="0" data-error="false">0</div>
36	  <div class="keys">
37	    <button class="clear wide" data-testid="key-clear">AC</button>
38	    <button class="op" data-testid="key-div" data-op="/">÷</button>
39	    <button class="op" data-testid="key-mul" data-op="*">×</button>
40	    <button data-testid="key-7" data-digit="7">7</button>
41	    <button data-testid="key-8" data-digit="8">8</button>
42	    <button data-testid="key-9" data-digit="9">9</button>
43	    <button class="op" data-testid="key-sub" data-op="-">−</button>
44	    <button data-testid="key-4" data-digit="4">4</button>
45	    <button data-testid="key-5" data-digit="5">5</button>
46	    <button data-testid="key-6" data-digit="6">6</button>
47	    <button class="op" data-testid="key-add" data-op="+">+</button>
48	    <button data-testid="key-1" data-digit="1">1</button>
49	    <button data-testid="key-2" data-digit="2">2</button>
50	    <button data-testid="key-3" data-digit="3">3</button>
51	    <button class="op" data-testid="key-equals">=</button>
52	    <button class="wide" data-testid="key-0" data-digit="0">0</button>
53	    <button data-testid="key-dot">.</button>
54	  </div>
55	</div>
56	<script>
57	  var entry = "0";      // text of the current entry or last result
58	  var stored = null;    // left operand
59	  var op = null;        // pending operator
60	  var fresh = true;     // next digit starts a new entry
61	  var error = false;    // set by a non-finite result; only clear leaves it
62	
63	  var display = document.querySelector('[data-testid="calc-display"]');
64	
65	  function compute(a, b, o) {
66	    if (o === "+") return a + b;
67	    if (o === "-") return a - b;
68	    if (o === "*") return a * b;
69	    return a / b;
70	  }
71	
72	  // Presentation only: at most 10 significant digits, no trailing zeros,
73	  // exponential below 1e-9 or from 1e10. Stored values are never rounded.
74	  function format(v) {
75	    if (v === 0) return "0";
76	    var r = Number(v.toPrecision(10));
77	    var a = Math.abs(r);
78	    if (a >= 1e10 || a < 1e-9) return r.toExponential();
79	    var e = Math.floor(Math.log10(a));
80	    if (Math.pow(10, e) > a) e--;
81	    var s = r.toFixed(Math.max(0, 9 - e));
82	    return s.indexOf(".") === -1 ? s : s.replace(/0+$/, "").replace(/\.$/, "");
83	  }
84	
85	  // While typing, the entry shows exactly as typed; results are formatted.
86	  function render() {
87	    display.textContent = error ? "Error" : fresh ? format(Number(entry)) : entry;
88	    display.setAttribute("data-value", String(Number(entry)));
89	    display.setAttribute("data-error", String(error));
90	  }
91	
92	  function digit(d) {
93	    if (fresh) { entry = d; fresh = false; }
94	    else entry = entry === "0" ? d : entry + d;
95	  }
96	
97	  function dot() {
98	    if (fresh) { entry = "0."; fresh = false; }
99	    else if (entry.indexOf(".") === -1) entry += ".";
100	  }
101	
102	  // Immediate execution: each operator finishes the waiting operation, strictly
103	  // left to right, no precedence. 2 + 3 × 4 = is 20. The display always shows a real result.
104	  function operator(o) {
105	    if (op !== null && !fresh) finish(compute(stored, Number(entry), op));
106	    stored = Number(entry);
107	    op = o;
108	    fresh = true;
109	  }
110	
111	  // Division by zero (or any non-finite result) enters the error state.
112	  function finish(result) {
113	    entry = String(result);
114	    if (!isFinite(result)) error = true;
115	  }
116	
117	  function equals() {
118	    if (op === null) return;
119	    finish(compute(stored, Number(entry), op));
120	    stored = null;
121	    op = null;
122	    fresh = true;
123	  }
124	
125	  function clear() {
126	    entry = "0"; stored = null; op = null; fresh = true; error = false;
127	  }
128	
129	  document.querySelector(".keys").addEventListener("click", function (e) {
130	    var b = e.target.closest("button");
131	    if (!b) return;
132	    var id = b.getAttribute("data-testid");
133	    if (error && id !== "key-clear") return;
134	    if (b.hasAttribute("data-digit")) digit(b.getAttribute("data-digit"));
135	    else if (b.hasAttribute("data-op")) operator(b.getAttribute("data-op"));
136	    else if (id === "key-dot") dot();
137	    else if (id === "key-equals") equals();
138	    else if (id === "key-clear") clear();
139	    render();
140	  });
141	
142	  render();
143	</script>
144	</body>
145	</html>
